def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    last_m, last_o = history[-1]
    if n == 1:
        return 'D' if last_o == 'D' else 'C'
    if n >= 99:
        return 'D'

    prev_m = history[-2][0]

    opp_d = 0
    opp_d10 = 0
    recent_unprov = 0
    unprov = 0
    c_after_c = 0
    last_forg = -1
    last_pun = -1

    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1
            if i >= n - 10:
                opp_d10 += 1

    for i in range(1, n):
        if history[i - 1][0] == 'C':
            if history[i][1] == 'D':
                unprov += 1
                if i >= n - 10:
                    recent_unprov += 1
            else:
                c_after_c += 1
        else:
            if history[i][1] == 'D':
                last_pun = i
            else:
                last_forg = i

    hostile = False
    if opp_d >= 4 and c_after_c == 0:
        hostile = True
    if opp_d >= 5 and unprov >= max(3, n // 8) and opp_d * 2 >= n:
        hostile = True
    if opp_d10 >= 8 and recent_unprov >= 3:
        hostile = True
    if unprov >= 5 and unprov * 2 >= opp_d and opp_d >= 4:
        hostile = True

    exploit = (last_forg > last_pun and last_forg >= n - 15)

    if last_o == 'C':
        if hostile:
            return 'D'
        if exploit:
            return 'D'
        if n >= 85 and last_forg > last_pun and last_forg != -1 and opp_d * 4 <= n:
            return 'D'
        return 'C'

    if hostile:
        return 'D'

    if prev_m == 'D':
        if c_after_c == 0 and opp_d >= 3:
            return 'D'
        if opp_d >= 6 and unprov >= 4:
            return 'D'
        return 'C'

    return 'D'
